#define CUI__GROW(ui, arr, count, cap, need) do {                                 \
    if ((count) + (need) > (cap)) {                                               \
        int ncap__ = (cap) ? (cap) * 2 : 64;                                      \
        while (ncap__ < (count) + (need)) ncap__ *= 2;                            \
        (arr) = cui__realloc((ui), (arr), sizeof(*(arr)) * (size_t)ncap__);        \
        (cap) = ncap__;                                                           \
    }                                                                             \
} while (0)

