static int combining(uint32_t cp) {
    int lo=0,hi=(int)(sizeof cui_combining/sizeof *cui_combining);
    while (lo<hi) {
        int m=lo+(hi-lo)/2;
        if (cp<cui_combining[m].cp) hi=m;
        else if (cp>cui_combining[m].cp) lo=m+1;
        else return cui_combining[m].value;
    }
    return 0;
}
static int modifier(uint32_t cp) {
    /* Unicode TR53 modifier combining marks, reordered closest to the base. */
    return cp==0x654 || cp==0x655 || cp==0x658 || cp==0x6dc || cp==0x6e3 ||
           cp==0x6e7 || cp==0x6e8 || cp==0x8ca || cp==0x8cb || cp==0x8cd ||
           cp==0x8ce || cp==0x8cf || cp==0x8d3 || cp==0x8f3;
}
static int normalize(cui_shape_font *f,cui_shape_glyph *g,int n,int arabic) {
    /* Canonical order, then compose only when the font has the composed glyph. */
    for (int i=0;i<n;i++) {
        int c=combining(g[i].codepoint);
        g[i].form=arabic?(c==33?27:c>=27 && c<33?c+1:c):c;
    }
    for (int i=1;i<n;i++) {
        int c=g[i].form;
        for (int j=i;c && j>0 && g[j-1].form>c;j--) {
            cui_shape_glyph t=g[j]; g[j]=g[j-1]; g[j-1]=t;
        }
    }
    if (arabic) for (int start=0;start<n;) {
        if (!g[start].form) { start++; continue; }
        int end=start+1;
        while (end<n && g[end].form) end++;
        int front=start;
        for (int c=220;c<=230;c+=10) {
            int at=front;
            while (at<end && g[at].form<c) at++;
            int last=at;
            while (last<end && g[last].form==c && modifier(g[last].codepoint)) last++;
            for (int k=at;k<last;k++) {
                cui_shape_glyph t=g[k]; t.form=c==220?25:26;
                memmove(g+front+1,g+front,(size_t)(k-front)*sizeof *g);
                g[front++]=t;
            }
        }
        start=end;
    }
    int base=-1,last=0;
    for (int i=0;i<n;i++) {
        int c=g[i].form,composed=0;
        if (base>=0 && c && (last<c || !last)) {
            for (unsigned k=0;k<sizeof cui_compositions/sizeof *cui_compositions;k++)
                if (g[base].codepoint==cui_compositions[k].base && g[i].codepoint==cui_compositions[k].mark && cui__shape_map(f,cui_compositions[k].cp)) {
                    g[base].codepoint=cui_compositions[k].cp;
                    memmove(g+i,g+i+1,(size_t)(n-i-1)*sizeof *g); n--; i--; composed=1; break;
                }
        }
        if (composed) continue;
        if (!c) base=i;
        last=c;
    }
    return n;
}
static int joining(uint32_t cp) {
    int lo=0,hi=(int)(sizeof cui_joining/sizeof *cui_joining);
    while (lo<hi) {
        int m=lo+(hi-lo)/2;
        if (cp<cui_joining[m].first) hi=m;
        else if (cp>cui_joining[m].first+cui_joining[m].span) lo=m+1;
        else return cui_joining[m].type;
    }
    return 0;
}
int cui__shape(cui_shape_font *f,cui_shape_glyph *g,int count,int capacity,uint32_t script,int rtl,int tabular) {
    if (count<0 || count>capacity || !f->cmap) return -1;
    count=normalize(f,g,count,script==TAG('a','r','a','b'));
    shape s={f,g,count,capacity,rtl,0,0,0,0,0};
    int prev=-1,prev_type=0;
    for (int i=0;i<count;i++) {
        g[i].id=cui__shape_map(f,g[i].codepoint); g[i].x=g[i].y=0;
        g[i].form=-1; g[i].ligature=g[i].component=0;
        int jt=joining(g[i].codepoint);
        if (script==TAG('a','r','a','b') && jt!=4) {
            if (jt) g[i].form=0;
            if (prev>=0 && (prev_type&1) && (jt&2)) {
                g[prev].form=g[prev].form==1?2:3; g[i].form=1;
            }
            prev=i; prev_type=jt;
        }
    }
    static const off tags[]={TAG('r','t','l','a'),TAG('r','t','l','m'),TAG('s','t','c','h'),TAG('c','c','m','p'),TAG('l','o','c','l'),
        TAG('i','s','o','l'),TAG('f','i','n','a'),TAG('m','e','d','i'),TAG('i','n','i','t'),TAG('r','l','i','g'),TAG('c','a','l','t'),
        TAG('r','c','l','t'),TAG('l','i','g','a'),TAG('c','l','i','g'),TAG('m','s','e','t')};
    s.layout=f->gsub; s.list=rel(f,s.layout,u16(f,s.layout+8));
    off lang=language(f,s.layout,script);
    for (int k=0;k<(int)(sizeof tags/sizeof *tags);k++) {
        if (k<2 && !rtl) continue;
        if (k==9) for (int i=0;i<s.n;i++) g[i].form=-1;
        feature(&s,lang,tags[k],k>=5 && k<=8?k-5:-1);
    }
    if (tabular) feature(&s,lang,TAG('t','n','u','m'),-1);
    for (int i=0;i<s.n;i++) {
        int glyph=g[i].id;
        g[i].advance=u16(f,f->hmtx+4*(glyph<f->metrics?glyph:f->metrics-1));
        if (glyph_class(&s,i)==3) g[i].advance=0;
    }
    s.position=1; s.layout=f->gpos; s.list=rel(f,s.layout,u16(f,s.layout+8)); lang=language(f,s.layout,script);
    static const off pos[]={TAG('c','u','r','s'),TAG('k','e','r','n'),TAG('m','a','r','k'),TAG('m','k','m','k'),TAG('d','i','s','t')};
    for (int k=0;k<5;k++) feature(&s,lang,pos[k],-1);
    for (int i=0;i<s.n;i++) if ((g[i].codepoint>=0x200b && g[i].codepoint<=0x200f) || (g[i].codepoint>=0x202a && g[i].codepoint<=0x202e) || (g[i].codepoint>=0x2066 && g[i].codepoint<=0x2069)) {
        g[i].id=cui__shape_map(f,' '); g[i].advance=g[i].x=g[i].y=0;
    }
    if (rtl) for (int i=0;i<s.n/2;i++) { cui_shape_glyph t=g[i]; g[i]=g[s.n-1-i]; g[s.n-1-i]=t; }
    return s.failed?-1:s.n;
}
#endif

/* ==== src/cui_social.c ==== */
/* Conversation: chat bubbles, typing indicator, comments and presence. */


static cui_color cui__accent_bg(cui_ctx *ui) { return ui->accent == CUI_ACCENT_NEUTRAL ? CUI_C(ui, CONTROL_ON) : CUI_C(ui, ACCENT); }
static cui_color cui__accent_text(cui_ctx *ui) { return ui->accent == CUI_ACCENT_NEUTRAL ? CUI_C(ui, CONTROL_GLYPH) : CUI_C(ui, ACCENT_FOREGROUND); }

/* ------------------------------------------------------------------------ */
/* Chat                                                                     */
/* ------------------------------------------------------------------------ */

void cui_chat_message_ex(cui_ctx *ui, const char *text, const cui_chat_opts *o) {
    cui_chat_opts d;
    memset(&d, 0, sizeof d);
    if (!o) o = &d;
    if (!text) text = "";
    /* new messages ease in */
    cui_id mid = cui__position_id(ui, cui__hash_str(text, 0xC4A7u));
    cui_id mdid = cui__position_id(ui, 0x4D44u);   /* without the text, so a streamed reply keeps its state */
    float *in = cui_state(ui, mid, sizeof(float) * 2);
    if (in[1] == 0) { in[1] = 1; in[0] = ui->frame <= 2 ? 1.0f : 0.0f; }
    cui__tween(ui, &in[0], 1.0f, 0.22f);
    int row = cui__node_new(ui, 0);
    cui_node *rn = &ui->nodes[row];
    rn->dir = CUI_ROW; rn->gap = 8; rn->align = CUI_ALIGN_END;
    rn->w = CUI_FILL; rn->self_align = CUI_ALIGN_STRETCH;
    rn->justify = o->mine ? CUI_JUSTIFY_END : CUI_JUSTIFY_START;
    rn->pad[0] = o->grouped ? 2 : 10;
    rn->opacity = CUI_MAX(0.001f, in[0]);
    rn->ty = (1.0f - in[0]) * 8;
    cui__open(ui, row);
    if (!o->mine) {
        if (o->last_in_group || !o->grouped) {
            cui_avatar_opts ao;
            memset(&ao, 0, sizeof ao);
            ao.size = 28; ao.image = o->avatar;
            if (o->last_in_group) cui_avatar_ex(ui, o->author ? o->author : "?", &ao);
            else cui_gap(ui, 28);
        } else cui_gap(ui, 28);
    }
    int col = cui__node_new(ui, 0);
    cui_node *cn = &ui->nodes[col];
    cn->gap = 3; cn->align = o->mine ? CUI_ALIGN_END : CUI_ALIGN_START;
    cn->max_w = 480;
    cui__open(ui, col);
    if (!o->grouped && (o->author || o->time) && !o->mine) {
        int head = cui__node_new(ui, 0);
        ui->nodes[head].dir = CUI_ROW; ui->nodes[head].gap = 6; ui->nodes[head].pad[3] = 4;
        cui__open(ui, head);
        if (o->author) {
            int a = cui__text_node(ui, o->author, -1, CUI_FONT_MEDIUM, cui__fs(ui, ui->theme.text_xs), CUI_C(ui, TEXT_SECONDARY), false);
            ui->nodes[a].line_height = 1.3f;
        }
        if (o->time) {
            int t = cui__text_node(ui, o->time, -1, CUI_FONT_BODY, cui__fs(ui, ui->theme.text_xs), CUI_C(ui, TEXT_MUTED), false);
            ui->nodes[t].line_height = 1.3f;
        }
        cui__close(ui);
    }
    int bubble = cui__node_new(ui, 0);
    cui_node *bn = &ui->nodes[bubble];
    bn->pad[0] = bn->pad[2] = 8; bn->pad[1] = bn->pad[3] = 13;
    float big = 18, small = 6;
    if (o->mine) bn->radius = (cui_corners){ big, o->grouped ? small : big, o->last_in_group ? big : small, big };
    else bn->radius = (cui_corners){ o->grouped ? small : big, big, big, o->last_in_group ? big : small };
    if (o->mine) bn->bg = cui__accent_bg(ui);
    else bn->bg = ui->mode == CUI_THEME_DARK ? cui_mix(CUI_C(ui, SURFACE), CUI_C(ui, FOREGROUND), 0.08f) : CUI_C(ui, SURFACE_MUTED);
    cui__open(ui, bubble);
    if (o->markdown) {
        cui_markdown_opts mo;
        memset(&mo, 0, sizeof mo);
        mo.compact = true;
        mo.fit_content = true;
        if (o->mine) mo.color = cui__accent_text(ui);
        cui_push_id_int(ui, (int)mdid);
        cui_markdown_result mr = cui_markdown_ex(ui, "md", text, &mo);
        cui_pop_id(ui);
        if (o->markdown_result) *o->markdown_result = mr;
    } else {
        int t = cui__text_node(ui, text, -1, CUI_FONT_BODY, cui__fs(ui, ui->theme.text_body), o->mine ? cui__accent_text(ui) : CUI_C(ui, FOREGROUND), true);
        ui->nodes[t].line_height = 1.45f;
    }
    cui__close(ui);
    if (o->mine && o->status && (o->last_in_group || !o->grouped)) {
        int st = cui__node_new(ui, 0);
        ui->nodes[st].dir = CUI_ROW; ui->nodes[st].gap = 4; ui->nodes[st].align = CUI_ALIGN_CENTER; ui->nodes[st].pad[1] = 4;
        cui__open(ui, st);
        cui__icon_node(ui, CUI_ICON_CHECK_CHECK, 12, cui__edge_on(ui));
        int s = cui__text_node(ui, o->time ? cui__frame_printf(ui, "%s %s", o->status, o->time) : o->status, -1, CUI_FONT_BODY,
                               cui__fs(ui, ui->theme.text_xs), CUI_C(ui, TEXT_MUTED), false);
        ui->nodes[s].line_height = 1.3f;
        cui__close(ui);
    }
    cui__close(ui);
    cui__close(ui);
}

void cui_chat_divider(cui_ctx *ui, const char *label) {
    int row = cui__node_new(ui, 0);
    ui->nodes[row].dir = CUI_ROW; ui->nodes[row].gap = 12; ui->nodes[row].align = CUI_ALIGN_CENTER;
    ui->nodes[row].w = CUI_FILL; ui->nodes[row].pad[0] = 14; ui->nodes[row].pad[2] = 6;
    cui__open(ui, row);
    int l = cui__leaf(ui, 0, CUI_FILL, CUI_PX(1));
    ui->nodes[l].bg = CUI_C(ui, BORDER);
    int t = cui__text_node(ui, label, -1, CUI_FONT_MEDIUM, cui__fs(ui, ui->theme.text_xs), CUI_C(ui, TEXT_MUTED), false);
    ui->nodes[t].line_height = 1.2f;
    int r = cui__leaf(ui, 0, CUI_FILL, CUI_PX(1));
    ui->nodes[r].bg = CUI_C(ui, BORDER);
    cui__close(ui);
}

typedef struct { double time; cui_color c; } cui__dots_paint;
static void cui__paint_typing(cui_ctx *ui, cui_node *n, void *data) {
    cui__dots_paint *p = data;
    cui_rect r = n->rect;
    for (int k = 0; k < 3; k++) {
        float ph = (float)p->time * 7.0f - k * 0.7f;
        float b = 0.5f + 0.5f * sinf(ph);
        float y = r.y + r.h * 0.5f - b * 3.0f;
        cui_draw_circle(ui, (cui_vec2){ r.x + 5 + k * 9.0f, y }, 3.0f, cui_alpha(p->c, 0.45f + 0.55f * b));
    }
}

void cui_typing_indicator(cui_ctx *ui, const char *name) {
    int row = cui__node_new(ui, 0);
    ui->nodes[row].dir = CUI_ROW; ui->nodes[row].gap = 8; ui->nodes[row].align = CUI_ALIGN_END; ui->nodes[row].pad[0] = 8;
    cui__open(ui, row);
    cui_avatar_opts ao;
    memset(&ao, 0, sizeof ao);
    ao.size = 28;
    cui_avatar_ex(ui, name ? name : "?", &ao);
    int bubble = cui__node_new(ui, 0);
    cui_node *bn = &ui->nodes[bubble];
    bn->pad[0] = bn->pad[2] = 13; bn->pad[1] = bn->pad[3] = 14;
    bn->radius = (cui_corners){ 18, 18, 18, 6 };
    bn->bg = ui->mode == CUI_THEME_DARK ? cui_mix(CUI_C(ui, SURFACE), CUI_C(ui, FOREGROUND), 0.08f) : CUI_C(ui, SURFACE_MUTED);
    cui__open(ui, bubble);
    int dots = cui__leaf(ui, 0, CUI_PX(28), CUI_PX(12));
    cui__dots_paint *p = cui__frame_alloc(ui, sizeof *p);
    p->time = ui->time; p->c = CUI_C(ui, TEXT_SECONDARY);
    ui->nodes[dots].paint = cui__paint_typing;
    ui->nodes[dots].paint_data = p;
    cui__close(ui);
    if (name) {
        int t = cui__text_node(ui, cui__frame_printf(ui, "%s is typing", name), -1, CUI_FONT_BODY, cui__fs(ui, ui->theme.text_xs), CUI_C(ui, TEXT_MUTED), false);
        ui->nodes[t].line_height = 1.3f;
        ui->nodes[t].self_align = CUI_ALIGN_CENTER;
    }
    cui__close(ui);
    ui->animating = true;
}

/* ------------------------------------------------------------------------ */
/* Comments                                                                 */
/* ------------------------------------------------------------------------ */

/* where each depth's last avatar ended, written as rows paint, so a reply's rail starts under its parent's avatar */
typedef struct { float bottom[8]; } cui__thread_rail;
typedef struct { cui_color c; int depth; float indent, av, parent_indent, parent_av; cui__thread_rail *rail; } cui__thread_paint;
static void cui__paint_thread(cui_ctx *ui, cui_node *n, void *data) {
    cui__thread_paint *p = data;
    cui_rect r = n->rect;
    float ay = r.y + 6, mid = ay + p->av * 0.5f;
    if (p->depth > 0 && p->depth < 8) {
        /* down from the parent's avatar, then a soft elbow into this reply's avatar */
        float x = r.x + p->parent_indent + p->parent_av * 0.5f - 0.75f;
        float top = CUI_MIN(p->rail->bottom[p->depth - 1] + 6, mid - 8);
        float end = r.x + p->indent - 6;
        cui_draw_rect(ui, (cui_rect){ x, top, 1.5f, mid - 8 - top }, CUI_CORNERS(0.75f), p->c);
        cui_draw_arc(ui, (cui_vec2){ x + 8.75f, mid - 8 }, 8, CUI_PI * 0.5f, CUI_PI, 1.5f, p->c);
        if (end > x + 8.75f) cui_draw_rect(ui, (cui_rect){ x + 8.75f, mid - 0.75f, end - x - 8.75f, 1.5f }, CUI_CORNERS(0.75f), p->c);
    }
    if (p->depth < 8) p->rail->bottom[p->depth] = ay + p->av;
}

int cui_comment_ex(cui_ctx *ui, const char *id_str, const char *author, const char *text, const cui_comment_opts *o) {
    cui_comment_opts d;
    memset(&d, 0, sizeof d);
    if (!o) o = &d;
    int result = 0;
    float indent = 44.0f * (float)CUI_MAX(0, o->depth);
    float av = o->depth > 0 ? 28 : 34;
    cui_push_id(ui, id_str);
    int row = cui__node_new(ui, 0);
    cui_node *rn = &ui->nodes[row];
    rn->dir = CUI_ROW; rn->gap = 12; rn->align = CUI_ALIGN_START;
    rn->w = CUI_FILL; rn->pad[3] = indent; rn->pad[0] = 6; rn->pad[2] = 6;
    cui__thread_paint *tp = cui__frame_alloc(ui, sizeof *tp);
    tp->c = CUI_C(ui, BORDER);
    tp->depth = CUI_MAX(0, o->depth);
    tp->indent = indent; tp->av = av;
    tp->parent_indent = CUI_MAX(0.0f, indent - 44); tp->parent_av = o->depth > 1 ? 28 : 34;
    tp->rail = cui_state(ui, (cui_id)0x7EAD5EEDu, sizeof(cui__thread_rail));
    rn->paint = cui__paint_thread;
    rn->paint_data = tp;
    cui__open(ui, row);
    cui_avatar_opts ao;
    memset(&ao, 0, sizeof ao);
    ao.size = av;
    int avn = ui->node_count;
    cui_avatar_ex(ui, author, &ao);
    ui->nodes[avn].self_align = CUI_ALIGN_START;   /* beside the name, not the middle of a long comment */
    int col = cui__node_new(ui, 0);
    ui->nodes[col].w = CUI_FILL; ui->nodes[col].gap = 4;
    cui__open(ui, col);
    int head = cui__node_new(ui, 0);
    ui->nodes[head].dir = CUI_ROW; ui->nodes[head].gap = 8; ui->nodes[head].align = CUI_ALIGN_CENTER;
    cui__open(ui, head);
    int an = cui__text_node(ui, author, -1, CUI_FONT_MEDIUM, cui__fs(ui, ui->theme.text_sm), CUI_C(ui, FOREGROUND), false);
    ui->nodes[an].line_height = 1.4f;
    if (o->badge) {
        cui_badge_opts bo;
        memset(&bo, 0, sizeof bo);
        bo.size = CUI_SIZE_SM;
        cui_badge_ex(ui, o->badge, &bo);
    }
    if (o->time) {
        int tt = cui__text_node(ui, o->edited ? cui__frame_printf(ui, "%s \xc2\xb7 edited", o->time) : o->time, -1, CUI_FONT_BODY,
                                cui__fs(ui, ui->theme.text_xs), CUI_C(ui, TEXT_MUTED), false);
        ui->nodes[tt].line_height = 1.4f;
    }
    cui__close(ui);
    int body = cui__text_node(ui, text, -1, CUI_FONT_BODY, cui__fs(ui, ui->theme.text_body), CUI_C(ui, FOREGROUND), true);
    ui->nodes[body].line_height = 1.5f;
    int acts = cui__node_new(ui, 0);
    ui->nodes[acts].dir = CUI_ROW; ui->nodes[acts].gap = 2; ui->nodes[acts].pad[0] = 2;
    ui->nodes[acts].tx = -11;   /* the first icon lines up with the text above */
    cui__open(ui, acts);
    cui_button_opts bo;
    memset(&bo, 0, sizeof bo);
    bo.size = CUI_SIZE_SM; bo.variant = CUI_BUTTON_GHOST; bo.icon = CUI_ICON_HEART;
    bool liked = o->liked && *o->liked;   /* liked tints the heart; no pill, so the row keeps its rhythm */
    bo.color = liked ? (ui->accent == CUI_ACCENT_NEUTRAL ? CUI_C(ui, DANGER) : CUI_C(ui, ACCENT)) : CUI_C(ui, TEXT_SECONDARY);
    const char *lk = o->likes && *o->likes > 0 ? cui__frame_printf(ui, "%d###like", *o->likes) : "###like";
    if (cui_button_ex(ui, lk, &bo)) {
        result |= CUI_COMMENT_LIKE;
        if (o->liked) {
            *o->liked = !*o->liked;
            if (o->likes) *o->likes += *o->liked ? 1 : -1;
        }
    }
    memset(&bo, 0, sizeof bo);
    bo.size = CUI_SIZE_SM; bo.variant = CUI_BUTTON_GHOST; bo.icon = CUI_ICON_MESSAGE_SQUARE;
    bo.color = CUI_C(ui, TEXT_SECONDARY);
    if (cui_button_ex(ui, "Reply", &bo)) result |= CUI_COMMENT_REPLY;
    cui__close(ui);
    cui__close(ui);
    cui__close(ui);
    cui_pop_id(ui);
    return result;
}

/* ------------------------------------------------------------------------ */
/* Presence                                                                 */
/* ------------------------------------------------------------------------ */

typedef struct { cui_spring spread; } cui__pres_state;

void cui_presence(cui_ctx *ui, const char *id_str, const cui_presence_user *users, int count, int max_visible, float size) {
    if (size <= 0) size = 30;
    if (max_visible <= 0) max_visible = 5;
    cui_id id = cui_make_id(ui, id_str);
    cui__pres_state *st = cui_state(ui, id, sizeof *st);
    cui_interact r = cui__interact(ui, id, 0);
    cui__spring(ui, &st->spread, r.hovered ? 1.0f : 0.0f, CUI_SPRING_SNAPPY);
    float t = cui__clampf(st->spread.x, 0, 1.2f);
    float ring = 2, outer = size + ring * 2 + 2;
    int row = cui__node_new(ui, id);
    cui_node *rn = &ui->nodes[row];
    rn->dir = CUI_ROW; rn->align = CUI_ALIGN_CENTER;
    rn->gap = cui__lerp(-outer * 0.24f, 4, t);   /* overlapped, yet the next ring stops short of two wide initials */
    rn->self_align = CUI__ALIGN_NOSTRETCH;
    cui__mark_interactive(ui, row, 0);
    cui__open(ui, row);
    int shown = CUI_MIN(count, max_visible);
    for (int k = 0; k < shown; k++) {
        const cui_presence_user *u = &users[k];
        cui_id uid = cui__hash(&k, sizeof k, id);
        cui_interact ur = cui__interact(ui, uid, 0);
        int w = cui__node_new(ui, uid);
        cui_node *wn = &ui->nodes[w];
        wn->w = CUI_PX(outer); wn->h = CUI_PX(outer);
        wn->radius = CUI_CORNERS(outer * 0.5f);
        wn->bg = CUI_C(ui, BACKGROUND);          /* cuts the avatar out of its neighbor */
        wn->dir = CUI_STACK; wn->align = CUI_ALIGN_CENTER; wn->justify = CUI_JUSTIFY_CENTER;
        cui__mark_interactive(ui, w, 0);
        cui__open(ui, w);
        int ringn = cui__node_new(ui, 0);
        cui_node *rg = &ui->nodes[ringn];
        rg->w = CUI_PX(size + ring * 2); rg->h = CUI_PX(size + ring * 2);
        rg->radius = CUI_CORNERS((size + ring * 2) * 0.5f);
        rg->border = ring;
        rg->border_color = u->idle ? CUI_C(ui, BORDER_STRONG) : (cui__color_set(u->color) ? cui_color_of(ui, u->color) : cui__accent_bg(ui));
        rg->dir = CUI_STACK; rg->align = CUI_ALIGN_CENTER; rg->justify = CUI_JUSTIFY_CENTER;
        cui__open(ui, ringn);
        cui_avatar_opts ao;
        memset(&ao, 0, sizeof ao);
        ao.size = size - 2; ao.image = u->avatar;
        cui_avatar_ex(ui, u->name, &ao);
        if (u->idle) ui->nodes[ui->last_node].opacity = 0.55f;
        cui__close(ui);
        cui__close(ui);
        if (ur.hovered || r.hovered) {
            ui->last_id = uid;
            cui_tooltip(ui, u->idle ? cui__frame_printf(ui, "%s (away)", u->name) : u->name);
        }
    }
    if (count > shown) {
        int m = cui__node_new(ui, 0);
        cui_node *mn = &ui->nodes[m];
        mn->w = CUI_PX(outer); mn->h = CUI_PX(outer);
        mn->radius = CUI_CORNERS(outer * 0.5f);
        mn->bg = CUI_C(ui, BACKGROUND);
        mn->dir = CUI_STACK; mn->align = CUI_ALIGN_CENTER; mn->justify = CUI_JUSTIFY_CENTER;
        cui__open(ui, m);
        int in = cui__node_new(ui, 0);
        cui_node *inn = &ui->nodes[in];
        inn->w = CUI_PX(size + ring * 2); inn->h = CUI_PX(size + ring * 2);
        inn->radius = CUI_CORNERS((size + ring * 2) * 0.5f);
        inn->bg = CUI_C(ui, SURFACE_MUTED); inn->border = 1; inn->border_color = CUI_C(ui, BORDER);
        inn->dir = CUI_STACK; inn->align = CUI_ALIGN_CENTER; inn->justify = CUI_JUSTIFY_CENTER;
        cui__open(ui, in);
        int t2 = cui__text_node(ui, cui__frame_printf(ui, "+%d", count - shown), -1, CUI_FONT_MEDIUM, cui__fs(ui, size * 0.36f), CUI_C(ui, TEXT_SECONDARY), false);
        ui->nodes[t2].line_height = 1.0f;
        cui__close(ui);
        cui__close(ui);
    }
    cui__close(ui);
    ui->last_id = id;
}

/* ==== src/cui_strings.c ==== */
/* Text the components show: English by default, or an app's table (cui_set_strings).
 * Only the components that show dates link this file. */
#include <time.h>

static const cui_strings cui__english = {
    { "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" },
    { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" },
    { "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday" },
    { "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun" },
    { "Mo", "Tu", "We", "Th", "Fr", "Sa", "Su" },
    "Today",
};

void cui_set_strings(cui_ctx *ui, const cui_strings *strings) { ui->strings = strings; }
const cui_strings *cui_get_strings(cui_ctx *ui) { return ui->strings; }

/* the app's entry when it set one, else English; i is wrapped into range */
#define CUI__STR(field, n, i) \
    int k = ((i) % (n) + (n)) % (n); \
    const char *s = ui->strings ? ui->strings->field[k] : NULL; \
    return s ? s : cui__english.field[k]

const char *cui__month_name(cui_ctx *ui, int m) { CUI__STR(month, 12, m); }
const char *cui__month_short(cui_ctx *ui, int m) { CUI__STR(month_short, 12, m); }
const char *cui__weekday_name(cui_ctx *ui, int d) { CUI__STR(weekday, 7, d); }
const char *cui__weekday_short(cui_ctx *ui, int d) { CUI__STR(weekday_short, 7, d); }
const char *cui__weekday_min(cui_ctx *ui, int d) { CUI__STR(weekday_min, 7, d); }
const char *cui__today_text(cui_ctx *ui) { return ui->strings && ui->strings->today ? ui->strings->today : cui__english.today; }

/* a byte count: "512 bytes", "4.2 KB", "18 MB" (powers of 1000) */
const char *cui__size_text(cui_ctx *ui, double v) {
    if (v < 1000) return cui__frame_printf(ui, "%.0f bytes", v);
    static const char *u[] = { "KB", "MB", "GB", "TB" };
    int k = 0;
    v /= 1000;   /* at least 1 KB here */
    while (v >= 1000 && k < 3) { v /= 1000; k++; }
    return cui__frame_printf(ui, v < 10 ? "%.1f %s" : "%.0f %s", v, u[k]);
}

/* minutes east of UTC of the local time zone at time t */
int cui__utc_offset(int64_t t64) {
    time_t t = (time_t)t64;
    struct tm lt, gt;
#if defined(_WIN32)
    localtime_s(&lt, &t); gmtime_s(&gt, &t);
#else
    localtime_r(&t, &lt); gmtime_r(&t, &gt);
#endif
    int d = (lt.tm_year - gt.tm_year) * 366 + (lt.tm_yday - gt.tm_yday);
    if (d > 1) d = -1;
    if (d < -1) d = 1;
    return d * 1440 + (lt.tm_hour - gt.tm_hour) * 60 + (lt.tm_min - gt.tm_min);
}

/* ==== src/cui_terminal.c ==== */
/* Terminal: output with ANSI colors over an input line. Output is parsed as
 * it is written: line breaks, carriage returns and tabs act right away, color
 * sequences are kept in the text and read again when a line is drawn, and
 * everything else is dropped. Each line keeps its count of visible
 * characters, so wrapping needs no second pass over the text, and the paint
 * walks only the rows in view. */
#include <stdarg.h>


enum { CUI__TM_TEXT = 0, CUI__TM_ESC, CUI__TM_CSI, CUI__TM_OSC, CUI__TM_OSC_ESC };

/* ------------------------------------------------------------------------ */
/* Buffer                                                                   */
/* ------------------------------------------------------------------------ */

static cui_terminal_line *cui__tm_cur(cui_terminal_buffer *t) { return &t->lines[(t->first + t->count - 1) % t->line_cap]; }
static cui_terminal_line *cui__tm_line(const cui_terminal_buffer *t, int i) { return &t->lines[(t->first + i) % t->line_cap]; }

void cui_terminal_init(cui_terminal_buffer *t, char *text, size_t text_cap, cui_terminal_line *lines, int line_cap) {
    if (!t) return;
    memset(t, 0, sizeof *t);
    t->text = text; t->text_cap = (uint32_t)CUI_MIN(text_cap, (size_t)0x7FFFFFFF);
    t->lines = lines; t->line_cap = line_cap;
    if (!text || !lines || line_cap < 2 || t->text_cap < 64) { t->line_cap = 0; return; }
    t->count = 1; t->total = 1;
    lines[0] = (cui_terminal_line){ 0, 0, 0 };
}

void cui_terminal_clear(cui_terminal_buffer *t) {
    if (!t || !t->line_cap) return;
    t->first = 0; t->count = 1; t->end = 0; t->total++;
    t->lines[0] = (cui_terminal_line){ 0, 0, 0 };
    t->cr = false; t->mode = CUI__TM_TEXT;
}

static void cui__tm_new_line(cui_terminal_buffer *t) {
    if (t->count == t->line_cap) { t->first = (t->first + 1) % t->line_cap; t->count--; }
    t->lines[(t->first + t->count) % t->line_cap] = (cui_terminal_line){ t->end, 0, 0 };
    t->count++; t->total++;
}

/* room for n more bytes at the end of the current line, which stays in one piece */
static bool cui__tm_room(cui_terminal_buffer *t, uint32_t n) {
    cui_terminal_line *c = cui__tm_cur(t);
    if (c->len + n > t->text_cap) return false;   /* longer than the whole buffer */
    if (c->offset + c->len + n > t->text_cap) {
        /* wrap: the oldest lines live at the start; make way, then move the current line there */
        uint32_t need = c->len + n;
        while (t->count > 1) {
            cui_terminal_line *o = cui__tm_line(t, 0);
            if (o->offset < need) { t->first = (t->first + 1) % t->line_cap; t->count--; }
            else break;
        }
        memmove(t->text, t->text + c->offset, c->len);
        c->offset = 0;
        t->end = c->len;
    }
    /* older lines in the way of the bytes about to be written go */
    while (t->count > 1) {
        cui_terminal_line *o = cui__tm_line(t, 0);
        if (o->offset >= t->end && o->offset < t->end + n) { t->first = (t->first + 1) % t->line_cap; t->count--; }
        else break;
    }
    return true;
}

static void cui__tm_put(cui_terminal_buffer *t, const char *b, uint32_t n, uint32_t cols) {
    if (!cui__tm_room(t, n)) return;
    memcpy(t->text + t->end, b, n);
    t->end += n;
    cui_terminal_line *c = cui__tm_cur(t);
    c->len += n; c->cols += cols;
}

/* \r then output: the line starts over */
static void cui__tm_restart(cui_terminal_buffer *t) {
    cui_terminal_line *c = cui__tm_cur(t);
    t->end = c->offset; c->len = 0; c->cols = 0;
    t->cr = false;
}

void cui_terminal_write(cui_terminal_buffer *t, const char *data, int len) {
    if (!t || !t->line_cap || !data) return;
    if (len < 0) len = (int)strlen(data);
    int run = -1;   /* start of a run of plain text */
#define CUI__TM_FLUSH(upto) do { \
        if (run >= 0) { \
            uint32_t cols_ = 0; \
            for (int k_ = run; k_ < (upto); k_++) cols_ += ((unsigned char)data[k_] & 0xC0) != 0x80; \
            cui__tm_put(t, data + run, (uint32_t)((upto) - run), cols_); run = -1; } } while (0)
    for (int i = 0; i < len; i++) {
        unsigned char b = (unsigned char)data[i];
        switch (t->mode) {
        case CUI__TM_TEXT:
            if (b == 0x1b) { CUI__TM_FLUSH(i); t->mode = CUI__TM_ESC; t->seq_n = 0; t->seq[t->seq_n++] = (char)b; }
            else if (b == '\n') { CUI__TM_FLUSH(i); t->cr = false; cui__tm_new_line(t); }
            else if (b == '\r') { CUI__TM_FLUSH(i); t->cr = true; }
            else if (b == '\t') {
                CUI__TM_FLUSH(i);
                if (t->cr) cui__tm_restart(t);
                uint32_t sp = 8 - cui__tm_cur(t)->cols % 8;
                cui__tm_put(t, "        ", sp, sp);
            } else if (b == '\b') {
                CUI__TM_FLUSH(i);
                cui_terminal_line *c = cui__tm_cur(t);
                if (c->len > 0 && c->len == c->cols) { c->len--; c->cols--; t->end--; }   /* plain ASCII lines only */
            } else if (b < 0x20 || b == 0x7f) { CUI__TM_FLUSH(i); }   /* other controls: dropped */
            else {
                if (t->cr) { CUI__TM_FLUSH(i); cui__tm_restart(t); }
                if (run < 0) run = i;
            }
            break;
        case CUI__TM_ESC:
            if (b == '[') { t->mode = CUI__TM_CSI; if (t->seq_n < sizeof t->seq) t->seq[t->seq_n++] = (char)b; }
            else if (b == ']') t->mode = CUI__TM_OSC;
            else t->mode = CUI__TM_TEXT;   /* a two byte escape: dropped */
            break;
        case CUI__TM_CSI:
            if (t->seq_n < sizeof t->seq) t->seq[t->seq_n++] = (char)b;
            if (b >= 0x40 && b <= 0x7e) {
                t->mode = CUI__TM_TEXT;
                if (b == 'm' && t->seq[t->seq_n - 1] == 'm') {
                    if (t->cr) cui__tm_restart(t);
                    cui__tm_put(t, t->seq, t->seq_n, 0);
                } else if (b == 'K' && t->cr) cui__tm_restart(t);
                else if (b == 'J' && memchr(t->seq, '2', t->seq_n)) cui_terminal_clear(t);
            }
            break;
        case CUI__TM_OSC:
            if (b == 0x07) t->mode = CUI__TM_TEXT;
            else if (b == 0x1b) t->mode = CUI__TM_OSC_ESC;
            break;
        case CUI__TM_OSC_ESC:
            t->mode = b == '\\' ? CUI__TM_TEXT : CUI__TM_OSC;
            break;
        }
    }
    CUI__TM_FLUSH(len);
#undef CUI__TM_FLUSH
}

void cui_terminal_printf(cui_terminal_buffer *t, const char *fmt, ...) {
    char buf[2048];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    if (n > 0) cui_terminal_write(t, buf, CUI_MIN(n, (int)sizeof buf - 1));
}

/* ------------------------------------------------------------------------ */
/* Colors                                                                   */
/* ------------------------------------------------------------------------ */

typedef struct { cui_color fg, bg; bool has_fg, has_bg, bold, dim, italic, underline, inverse; } cui__tm_style;

static cui_color cui__tm_palette(cui_ctx *ui, int k) {
    /* tuned per mode so every color reads on the panel */
    static const uint32_t light[16] = { 0x27272a, 0xc4302b, 0x2e7d32, 0x9a6700, 0x1f5fbf, 0x8e3fb0, 0x0f7c84, 0x71717a,
                                        0x52525b, 0xe5484d, 0x30a46c, 0xb08300, 0x3e7bfa, 0xab4aba, 0x12a4ad, 0x18181b };
    static const uint32_t dark[16] = { 0x52525b, 0xff6b6b, 0x5bd18b, 0xf5c451, 0x6aa8ff, 0xd38cf2, 0x4fd1d9, 0xd4d4d8,
                                       0x71717a, 0xff8f8f, 0x7ee2a8, 0xffd97a, 0x93c0ff, 0xe2adf7, 0x7fe3e9, 0xfafafa };
    uint32_t v = (ui->mode == CUI_THEME_DARK ? dark : light)[k & 15];
    return cui__rgba((v >> 16) & 255, (v >> 8) & 255, v & 255, 255);
}

static cui_color cui__tm_256(cui_ctx *ui, int n) {
    if (n < 16) return cui__tm_palette(ui, n);
    if (n < 232) {
        n -= 16;
        static const int lv[6] = { 0, 95, 135, 175, 215, 255 };
        return cui__rgba(lv[n / 36], lv[n / 6 % 6], lv[n % 6], 255);
    }
    int g = 8 + (n - 232) * 10;
    return cui__rgba(g, g, g, 255);
}

/* applies "ESC [ p ; p ... m" to st */
static void cui__tm_sgr(cui_ctx *ui, cui__tm_style *st, const char *s, int n) {
    int p[16], np = 0, v = -1;
    for (int k = 2; k < n - 1 && np < 16; k++) {
        char c = s[k];
        if (c >= '0' && c <= '9') v = (v < 0 ? 0 : v) * 10 + (c - '0');
        else if (c == ';' || c == ':') { p[np++] = v < 0 ? 0 : v; v = -1; }
    }
    if (np < 16) p[np++] = v < 0 ? 0 : v;
    for (int k = 0; k < np; k++) {
        int c = p[k];
        if (c == 0) { memset(st, 0, sizeof *st); }
        else if (c == 1) st->bold = true;
        else if (c == 2) st->dim = true;
        else if (c == 3) st->italic = true;
        else if (c == 4) st->underline = true;
        else if (c == 7) st->inverse = true;
        else if (c == 22) st->bold = st->dim = false;
        else if (c == 23) st->italic = false;
        else if (c == 24) st->underline = false;
        else if (c == 27) st->inverse = false;
        else if (c >= 30 && c <= 37) { st->fg = cui__tm_palette(ui, c - 30); st->has_fg = true; }
        else if (c >= 90 && c <= 97) { st->fg = cui__tm_palette(ui, c - 90 + 8); st->has_fg = true; }
        else if (c >= 40 && c <= 47) { st->bg = cui__tm_palette(ui, c - 40); st->has_bg = true; }
        else if (c >= 100 && c <= 107) { st->bg = cui__tm_palette(ui, c - 100 + 8); st->has_bg = true; }
        else if (c == 39) st->has_fg = false;
        else if (c == 49) st->has_bg = false;
        else if ((c == 38 || c == 48) && k + 1 < np) {
            cui_color col;
            if (p[k + 1] == 5 && k + 2 < np) { col = cui__tm_256(ui, p[k + 2] & 255); k += 2; }
            else if (p[k + 1] == 2 && k + 4 < np) { col = cui__rgba(p[k + 2] & 255, p[k + 3] & 255, p[k + 4] & 255, 255); k += 4; }
            else continue;
            if (c == 38) { st->fg = col; st->has_fg = true; } else { st->bg = col; st->has_bg = true; }
        }
    }
}

/* ------------------------------------------------------------------------ */
/* View                                                                     */
/* ------------------------------------------------------------------------ */

typedef struct { uint64_t line; uint32_t col; } cui__tm_pos;   /* line number (total based) and visible column */

typedef struct {
    double top;                    /* first row in view */
    bool follow, init, selecting, has_sel;
    cui__tm_pos a, b;              /* selection: anchor and moving end */
    char input[1024];
    char hist[32][256]; int hn, hpos; bool browsing;
    float press_x, press_y;
} cui__tm_state;

typedef struct {
    const cui_terminal_buffer *t;   /* read during the paint only (the lines in view are unchanged until then) */
    double top; int cols; float cw, lh, size;
    bool has_sel; cui__tm_pos s0, s1;
    cui_color fg, sel, bar;
    float bar_t; double rows_total;
    cui_id wheel;
} cui__tm_paint;

static int cui__tm_rows(uint32_t cols, int width_cols) { return cols == 0 ? 1 : (int)((cols + (uint32_t)width_cols - 1) / (uint32_t)width_cols); }

/* block elements U+2580..U+2593: half and eighth blocks, and the three shades */
static void cui__tm_block(cui_ctx *ui, int k, cui_rect c, cui_color col) {
    float s = ui->scale > 0 ? ui->scale : 1;
    /* whole device pixels, so neighbouring cells meet without seams */
    float x0 = floorf(c.x * s + 0.5f) / s, x1 = floorf((c.x + c.w) * s + 0.5f) / s;
    float y0 = floorf(c.y * s + 0.5f) / s, y1 = floorf((c.y + c.h) * s + 0.5f) / s;
    float w = x1 - x0, h = y1 - y0;
    cui_rect r = { x0, y0, w, h };
    if (k == 0) r.h = floorf(h * 0.5f * s) / s;                                       /* upper half */
    else if (k >= 1 && k <= 8) { float f = k / 8.0f; r.y = y1 - floorf(h * f * s + 0.5f) / s; r.h = y1 - r.y; }   /* lower eighths up to full */
    else if (k >= 9 && k <= 15) r.w = floorf(w * (16 - k) / 8.0f * s + 0.5f) / s;         /* left eighths */
    else if (k == 16) { r.x = x0 + floorf(w * 0.5f * s) / s; r.w = x1 - r.x; }           /* right half */
    else if (k >= 17 && k <= 19) col = cui_alpha(col, (k - 16) * 0.25f);                /* light, medium, dark shade */
    cui_draw_rect(ui, r, CUI_CORNERS(0), col);
}

static void cui__paint_terminal(cui_ctx *ui, cui_node *n, void *data) {
    cui__tm_paint *p = data;
    cui_rect r = n->rect;
    cui__paint_wheel_hit(ui, p->wheel, r);
    const cui_terminal_buffer *t = p->t;
    if (!t || !t->line_cap) return;
    float pad = 10, x0 = r.x + pad, y0 = r.y + 6;
    float fh = cui__font_line_height(ui, CUI_FONT_MONO, p->size);
    /* find the line holding the first row in view */
    double row = 0;
    int li = 0;
    long long want = (long long)floor(p->top);
    while (li < t->count) {
        int rr = cui__tm_rows(cui__tm_line(t, li)->cols, p->cols);
        if (row + rr > want) break;
        row += rr; li++;
    }
    float y = y0 + (float)(row - p->top) * p->lh;
    /* rows show whole: one cut by the top edge is left out, as a terminal does */
    float first_y = y0 + (float)(floor(p->top) - p->top) * p->lh;
    float clip_top = first_y < y0 - 0.5f ? first_y + p->lh : r.y + 3;
    cui_push_clip(ui, (cui_rect){ r.x, clip_top, r.w, r.y + r.h - 3 - clip_top });
    uint64_t first_no = t->total - (uint64_t)t->count;
    cui__tm_pos s0 = p->s0, s1 = p->s1;
    for (; li < t->count && y < r.y + r.h; li++) {
        const cui_terminal_line *L = cui__tm_line(t, li);
        uint64_t no = first_no + (uint64_t)li;
        int nrows = cui__tm_rows(L->cols, p->cols);
        /* selection on this line, by visible column */
        if (p->has_sel && no >= s0.line && no <= s1.line) {
            uint32_t c0 = no == s0.line ? s0.col : 0, c1 = no == s1.line ? s1.col : L->cols + 1;
            for (uint32_t c = c0; c < c1;) {
                uint32_t rowi = c / (uint32_t)p->cols, end = CUI_MIN(c1, (rowi + 1) * (uint32_t)p->cols);
                float sy = y + rowi * p->lh;
                cui_draw_rect(ui, (cui_rect){ x0 + (c % (uint32_t)p->cols) * p->cw, sy, (end - c) * p->cw, p->lh }, CUI_CORNERS(0), p->sel);
                c = end;
            }
        }
        /* the text, run by run, wrapping at the column count */
        cui__tm_style st;
        memset(&st, 0, sizeof st);
        const char *s = t->text + L->offset;
        uint32_t i = 0, col = 0;
        while (i < L->len) {
            if ((unsigned char)s[i] == 0x1b) {
                uint32_t j = i + 1;
                while (j < L->len && !((unsigned char)s[j] >= 0x40 && (unsigned char)s[j] <= 0x7e && j > i + 1)) j++;
                if (j < L->len) cui__tm_sgr(ui, &st, s + i, (int)(j - i + 1));
                i = j + 1;
                continue;
            }
            /* plain text up to the next escape or the end of the row */
            uint32_t j = i, c = col, room = (uint32_t)p->cols - col % (uint32_t)p->cols;
            uint32_t taken = 0;
            while (j < L->len && (unsigned char)s[j] != 0x1b) {
                bool lead = ((unsigned char)s[j] & 0xC0) != 0x80;
                if (lead) { if (taken == room) break; taken++; }
                j++;
            }
            cui_color fg = st.has_fg ? st.fg : p->fg, bg = st.has_bg ? st.bg : cui__rgba(0, 0, 0, 0);
            if (st.inverse) { cui_color tmp = fg; fg = st.has_bg ? st.bg : CUI_C(ui, SURFACE); bg = tmp; }
            if (st.dim) fg = cui_alpha(fg, 0.6f);
            float rx = x0 + (c % (uint32_t)p->cols) * p->cw, ry = y + (c / (uint32_t)p->cols) * p->lh;
            if (ry > r.y + r.h) break;
            if (bg.a) cui_draw_rect(ui, (cui_rect){ rx, ry, taken * p->cw, p->lh }, CUI_CORNERS(0), bg);
            if (ry + p->lh >= r.y) {
                /* the grid: each character at its cell, so a font that is not quite monospaced still lines up.
                 * A run with right-to-left script is drawn whole instead, so it is shaped and put in order. */
                uint32_t k = i;
                float cx = rx;
                bool rtl = false;
                for (uint32_t q = i; q < j && !rtl; q++) {
                    unsigned char ch = (unsigned char)s[q];
                    rtl = (ch >= 0xD6 && ch <= 0xDF) || (ch == 0xEF && q + 1 < j && (unsigned char)s[q + 1] >= 0xAC && (unsigned char)s[q + 1] <= 0xBB);
                }
                if (rtl) {
                    uint32_t q = i;
                    while (q < j && s[q] == ' ') q++;   /* spaces before it keep their cells; bidi would move them to the far end */
                    cui__draw_text_line(ui, CUI_FONT_MONO, p->size, rx + (q - i) * p->cw, ry + (p->lh - fh) * 0.5f, fg, s + q, (int)(j - q), true);
                    k = j;
                }
                while (k < j) {
                    uint32_t e = k + 1;
                    while (e < j && ((unsigned char)s[e] & 0xC0) == 0x80) e++;
                    unsigned char b0 = (unsigned char)s[k];
                    if (e - k == 3 && b0 == 0xE2 && (unsigned char)s[k + 1] == 0x96 && (unsigned char)s[k + 2] >= 0x80 && (unsigned char)s[k + 2] <= 0x93) {
                        cui__tm_block(ui, (unsigned char)s[k + 2] - 0x80, (cui_rect){ cx, ry, p->cw, p->lh }, fg);   /* fonts rarely have these; drawn so bars join */
                    } else if (s[k] != ' ') {
                        cui__draw_text_line(ui, st.bold ? CUI_FONT_MONO : CUI_FONT_MONO, p->size, cx, ry + (p->lh - fh) * 0.5f, fg, s + k, (int)(e - k), true);
                        if (st.bold) cui__draw_text_line(ui, CUI_FONT_MONO, p->size, cx + 0.45f, ry + (p->lh - fh) * 0.5f, fg, s + k, (int)(e - k), true);
                    }
                    k = e; cx += p->cw;
                }
                if (st.underline) cui_draw_rect(ui, (cui_rect){ rx, ry + p->lh - 3, taken * p->cw, 1 }, CUI_CORNERS(0), fg);
            }
            col += taken; i = j;
        }
        y += nrows * p->lh;
    }
    cui_pop_clip(ui);
    /* a thin scrollbar while there is more above */
    if (p->bar_t > 0.01f && p->rows_total * p->lh > r.h) {
        float vh = r.h, th = CUI_MAX(24.0f, vh * vh / (float)(p->rows_total * p->lh));
        float maxtop = (float)(p->rows_total - (r.h - 12) / p->lh);
        float ty = r.y + (maxtop > 0 ? (float)(p->top / maxtop) : 1) * (vh - th);
        cui_draw_rect(ui, (cui_rect){ r.x + r.w - 6, ty, 3, th }, CUI_CORNERS(1.5f), cui_alpha(p->bar, p->bar_t));
    }
}

/* the visible text of line i between columns, escapes left out */
static size_t cui__tm_copy_line(const cui_terminal_buffer *t, int li, uint32_t c0, uint32_t c1, char *out, size_t cap) {
    const cui_terminal_line *L = cui__tm_line(t, li);
    const char *s = t->text + L->offset;
    size_t n = 0;
    uint32_t col = 0;
    for (uint32_t i = 0; i < L->len;) {
        if ((unsigned char)s[i] == 0x1b) {
            uint32_t j = i + 1;
            while (j < L->len && !((unsigned char)s[j] >= 0x40 && (unsigned char)s[j] <= 0x7e && j > i + 1)) j++;
            i = j + 1;
            continue;
        }
        uint32_t e = i + 1;
        while (e < L->len && ((unsigned char)s[e] & 0xC0) == 0x80) e++;
        if (col >= c0 && col < c1 && n + (e - i) < cap) { memcpy(out + n, s + i, e - i); n += e - i; }
        col++; i = e;
    }
    return n;
}

static cui_terminal_result cui__terminal_ex_body(cui_ctx *ui, const char *id_str, cui_terminal_buffer *t, const cui_terminal_opts *o);

/* left to right in any interface: see cui__keep_ltr */
cui_terminal_result cui_terminal_ex(cui_ctx *ui, const char *id_str, cui_terminal_buffer *t, const cui_terminal_opts *o) {
    int first = ui->node_count;
    cui_terminal_result r = cui__terminal_ex_body(ui, id_str, t, o);
    cui__keep_ltr(ui, first);
    return r;
}

static cui_terminal_result cui__terminal_ex_body(cui_ctx *ui, const char *id_str, cui_terminal_buffer *t, const cui_terminal_opts *o) {
    cui_terminal_opts d;
    memset(&d, 0, sizeof d);
    if (!o) o = &d;
    cui_terminal_result res = { NULL, false };
    cui_id id = cui_make_id(ui, id_str ? id_str : "terminal");
    cui_id vid = id ^ 0x7E2Du, wid = id ^ 0x7E2Eu;
    cui_id fid = cui__hash_str("#term-input", id);
    cui__tm_state *st = cui_state(ui, id, sizeof *st);
    if (!st->init) { st->follow = true; st->init = true; }
    float size = cui__fs(ui, o->size > 0 ? o->size : 13);
    float cw = cui__text_width(ui, CUI_FONT_MONO, size, "0", 1, true);
    if (cw <= 0) cw = size * 0.6f;
    float lh = ceilf(size * 1.45f);
    cui_rect pr = cui__prev_rect(ui, vid);
    float vw = pr.w > 0 ? pr.w : 600, vh = pr.h > 0 ? pr.h : (o->height > 0 ? o->height : 320) - 40;
    int cols = CUI_MAX(8, (int)((vw - 20) / cw));
    /* rows of the whole buffer at this width */
    double rows_total = 0;
    bool ok = t && t->line_cap;
    if (ok) for (int i = 0; i < t->count; i++) rows_total += cui__tm_rows(cui__tm_line(t, i)->cols, cols);
    double page = (vh - 12) / lh, maxtop = CUI_MAX(0.0, rows_total - page);
    cui_interact vr = cui__interact(ui, vid, CUI_IF_DRAG);
    if (ui->scroll_target == wid && ui->scroll_dy != 0) {
        st->top -= ui->scroll_dy * 3;
        st->follow = st->top >= maxtop - 0.5;
        ui->scroll_dy = 0;
    }
    if (st->follow) st->top = maxtop;
    st->top = CUI_CLAMP(st->top, 0, maxtop);
    if (st->top >= maxtop - 0.01) st->follow = true;
    /* the pointer as a text position */
    cui__tm_pos at = { 0, 0 };
    bool at_ok = false;
    if (ok && pr.w > 0) {
        double rr = st->top + (ui->my - pr.y - 6) / lh;
        if (rr < 0) rr = 0;
        double row = 0;
        int li = 0;
        while (li < t->count - 1) {
            int nr = cui__tm_rows(cui__tm_line(t, li)->cols, cols);
            if (row + nr > rr) break;
            row += nr; li++;
        }
        int sub = (int)(rr - row);
        long cc = (long)floorf((ui->mx - pr.x - 10) / cw + 0.5f);
        cc = CUI_CLAMP(cc, 0, cols);
        uint32_t col = (uint32_t)(sub * cols + cc);
        col = CUI_MIN(col, cui__tm_line(t, li)->cols);
        at = (cui__tm_pos){ t->total - (uint64_t)t->count + (uint64_t)li, col };
        at_ok = true;
    }
    if (vr.active && ui->mpressed[0] && at_ok) { st->a = st->b = at; st->selecting = true; st->has_sel = false; st->press_x = ui->mx; st->press_y = ui->my; }
    if (st->selecting && ui->mdown[0] && at_ok) {
        st->b = at;
        if (fabsf(ui->mx - st->press_x) + fabsf(ui->my - st->press_y) > 3) st->has_sel = true;
        /* dragging past the edge scrolls */
        if (ui->my < pr.y) { st->top = CUI_MAX(0.0, st->top - 0.5); st->follow = false; ui->animating = true; }
        if (ui->my > pr.y + pr.h) { st->top = CUI_MIN(maxtop, st->top + 0.5); ui->animating = true; }
    }
    if (st->selecting && !ui->mdown[0]) {
        st->selecting = false;
        ui->focus = o->no_input ? vid : fid;   /* keys reach the terminal; a click on the output types at the prompt */
    }
    if (vr.hovered) cui__set_cursor(ui, CUI_CURSOR_TEXT);
    cui__tm_pos s0 = st->a, s1 = st->b;
    if (s1.line < s0.line || (s1.line == s0.line && s1.col < s0.col)) { cui__tm_pos tmp = s0; s0 = s1; s1 = tmp; }
    /* the copy shortcut copies a selection; Ctrl+C without one interrupts; Ctrl+L clears */
    bool ours = ui->focus == fid || ui->focus == vid;
    bool field_sel = false;
    if (ui->focus == fid) { cui_edit_state *e = cui_state(ui, fid, sizeof(cui_edit_state)); field_sel = e->cursor != e->anchor; }
    if (ours && !field_sel && cui_key_pressed(ui, CUI_KEY_C) && (ui->mods & (CUI_MOD_CTRL | CUI_MOD_PRIMARY))) {
        if (st->has_sel && (ui->mods & CUI_MOD_PRIMARY)) {
            if (ok && ui->platform.set_clipboard) {
            size_t cap = 256 * 1024, n = 0;
            char *buf = cui__alloc(ui, cap);
            if (buf) {
                uint64_t first_no = t->total - (uint64_t)t->count;
                for (uint64_t no = CUI_MAX(s0.line, first_no); no <= s1.line && no < t->total; no++) {
                    int li = (int)(no - first_no);
                    uint32_t c0 = no == s0.line ? s0.col : 0, c1 = no == s1.line ? s1.col : 0xFFFFFFFFu;
                    n += cui__tm_copy_line(t, li, c0, c1, buf + n, cap - n - 2);
                    if (no != s1.line && n < cap - 2) buf[n++] = '\n';
                }
                buf[n] = 0;
                ui->platform.set_clipboard(ui->platform.user, buf);
                cui__free(ui, buf);
            }
            }
            st->has_sel = false;
            ui->kpressed[CUI_KEY_C] = 0;
        } else if (ui->mods & CUI_MOD_CTRL) {
            res.interrupt = true;
            if (ok) cui_terminal_write(t, "^C\n", 3);
            st->input[0] = 0;
            ui->kpressed[CUI_KEY_C] = 0;
        }
    }
    if (ours && cui_key_pressed(ui, CUI_KEY_L) && (ui->mods & CUI_MOD_CTRL) && ok) { cui_terminal_clear(t); st->top = 0; st->follow = true; st->has_sel = false; }
    /* history */
    if (ui->focus == fid && st->hn > 0) {
        int dir = cui_key_pressed(ui, CUI_KEY_UP) ? -1 : cui_key_pressed(ui, CUI_KEY_DOWN) ? 1 : 0;
        if (dir) {
            if (!st->browsing) { st->hpos = st->hn; st->browsing = true; }
            st->hpos = CUI_CLAMP(st->hpos + dir, 0, st->hn);
            snprintf(st->input, sizeof st->input, "%s", st->hpos < st->hn ? st->hist[st->hpos] : "");
            ui->tf_select_all = 0;
            cui_edit_state *e = cui_state(ui, fid, sizeof(cui_edit_state));
            e->cursor = e->anchor = (int)strlen(st->input);
            ui->kpressed[CUI_KEY_UP] = ui->kpressed[CUI_KEY_DOWN] = 0;
        }
    }

    float h = o->height > 0 ? o->height : 320;
    int col = cui__node_new(ui, id);
    cui_node *cn = &ui->nodes[col];
    cn->w = o->width.kind ? o->width : CUI_FILL;
    cn->h = o->height < 0 ? CUI_FILL : CUI_PX(h);
    cn->self_align = CUI_ALIGN_STRETCH; cn->gap = 0;
    cn->bg = ui->mode == CUI_THEME_DARK ? cui_mix(CUI_C(ui, BACKGROUND), CUI_C(ui, SURFACE), 0.5f) : CUI_C(ui, SURFACE);
    cn->border = 1; cn->border_color = CUI_C(ui, BORDER);
    cn->radius = CUI_CORNERS(ui->theme.radius_control);
    cn->flags |= CUI_NF_CLIP;
    cui__open(ui, col);
    int v = cui__leaf(ui, vid, CUI_FILL, CUI_FILL);
    ui->nodes[v].self_align = CUI_ALIGN_STRETCH;
    cui__mark_interactive(ui, v, 0);
    cui__tm_paint *p = cui__frame_alloc(ui, sizeof *p);
    memset(p, 0, sizeof *p);
    p->t = ok ? t : NULL; p->top = st->top; p->cols = cols; p->cw = cw; p->lh = lh; p->size = size;
    p->has_sel = st->has_sel; p->s0 = s0; p->s1 = s1;
    p->fg = CUI_C(ui, FOREGROUND);
    p->sel = cui_alpha(cui__emphasis(ui), ui->mode == CUI_THEME_DARK ? 0.3f : 0.18f);
    p->bar = CUI_C(ui, BORDER_STRONG); p->bar_t = vr.hovered || !st->follow ? 1 : 0; p->rows_total = rows_total;
    p->wheel = wid;
    ui->nodes[v].paint = cui__paint_terminal;
    ui->nodes[v].paint_data = p;
    if (!o->no_input) {
        int line = cui__leaf(ui, 0, CUI_FILL, CUI_PX(1));
        ui->nodes[line].bg = CUI_C(ui, BORDER_SUBTLE);
        int row = cui__node_new(ui, 0);
        cui_node *rn = &ui->nodes[row];
        rn->dir = CUI_ROW; rn->align = CUI_ALIGN_CENTER; rn->w = CUI_FILL; rn->h = CUI_PX(34);
        rn->pad[1] = rn->pad[3] = 10; rn->gap = 0;
        cui__open(ui, row);
        const char *prompt = o->prompt ? o->prompt : "$ ";
        int pt = cui__text_node(ui, prompt, -1, CUI_FONT_MONO, size, ui->accent == CUI_ACCENT_NEUTRAL ? CUI_C(ui, TEXT_SECONDARY) : CUI_C(ui, ACCENT), false);
        ui->nodes[pt].flags |= CUI_NF_TABULAR;
        cui_input_opts io;
        memset(&io, 0, sizeof io);
        io.width = CUI_FILL;
        ui->tf_override = true; ui->tf_font = CUI_FONT_MONO; ui->tf_size = size;
        int f = cui__text_field(ui, fid, st->input, sizeof st->input, &io, false, 1, NULL);
        if (f & CUI_CHANGED) st->browsing = false;
        if ((f & CUI_SUBMITTED)) {
            if (ok) { cui_terminal_write(t, "\x1b[2m", 4); cui_terminal_write(t, prompt, -1); cui_terminal_write(t, "\x1b[0m", 4); cui_terminal_write(t, st->input, -1); cui_terminal_write(t, "\n", 1); }
            if (st->input[0] && (st->hn == 0 || strcmp(st->hist[st->hn - 1], st->input))) {
                if (st->hn == 32) { memmove(st->hist[0], st->hist[1], sizeof st->hist[0] * 31); st->hn--; }
                size_t n = strlen(st->input), cap = sizeof st->hist[0] - 1;
                if (n > cap) { n = cap; while (n > 0 && ((unsigned char)st->input[n] & 0xC0) == 0x80) n--; }   /* whole characters */
                memcpy(st->hist[st->hn], st->input, n); st->hist[st->hn++][n] = 0;
            }
            res.command = cui__frame_strdup(ui, st->input, -1);
            st->input[0] = 0;
            st->browsing = false; st->follow = true;
            cui_edit_state *e = cui_state(ui, fid, sizeof(cui_edit_state));
            e->cursor = e->anchor = 0;
        }
        cui__close(ui);
    }
    cui__close(ui);
    ui->last_id = o->no_input ? vid : fid;
    return res;
}

/* ==== src/cui_text.c ==== */
/* Fonts and text: TrueType rasterization with stb_truetype, a glyph atlas
 * with subpixel positioning, kerning, font fallback (icons live in their own
 * font and work inside any string), measuring and word wrap. */

#define STBTT_STATIC
#define STB_TRUETYPE_IMPLEMENTATION
#if defined(__GNUC__) || defined(__clang__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"
#pragma GCC diagnostic ignored "-Wsign-compare"
#pragma GCC diagnostic ignored "-Wconversion"
#pragma GCC diagnostic ignored "-Wcast-qual"
#endif

